#!/usr/bin/env python3
"""Apply the experimentally earned cold-biography read-through mechanism."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

persistence_path = ROOT / "persona_engine" / "core" / "persistence.py"
engine_path = ROOT / "persona_engine" / "core" / "engine.py"

persistence = persistence_path.read_text(encoding="utf-8")
marker = "    def load_subject_continuity_events(\n"
if marker not in persistence:
    raise SystemExit("persistence insertion marker not found")
iterator_method = '''    def iter_continuity_events(\n        self,\n        character_id: str,\n        user_id: str,\n        *,\n        after_sequence: int = 0,\n        continuity_epoch: int | None = None,\n        event_type: str | None = None,\n    ):\n        \"\"\"Stream one interlocutor's canonical history without materializing it.\n\n        This is the low-memory archive read seam. The permanent subject binding\n        still anchors the stream, while ``user_id`` remains an explicit provenance\n        boundary so cold recall cannot leak another interlocutor's private history.\n        \"\"\"\n\n        subject_uuid, bound_epoch = self._resolve_subject(character_id, user_id)\n        epoch = bound_epoch if continuity_epoch is None else int(continuity_epoch)\n        query = (\n            \"SELECT event_uuid,subject_uuid,character_id,user_id,sequence,subject_sequence,continuity_epoch,subject_time,wall_time,source_actor,source_class,authority_class,event_type,visibility,canonicality,causal_parents,payload_schema,payload,legacy_event_id \"\n            \"FROM continuity_event WHERE subject_uuid=? AND user_id=? AND continuity_epoch=? AND sequence>?\"\n        )\n        params: list[Any] = [subject_uuid, user_id, epoch, int(after_sequence)]\n        if event_type is not None:\n            query += \" AND event_type=?\"\n            params.append(str(event_type))\n        query += \" ORDER BY sequence\"\n        conn = self._connect()\n        try:\n            cursor = conn.execute(query, tuple(params))\n            for row in cursor:\n                yield self._continuity_row_to_dict(row)\n        finally:\n            conn.close()\n\n'''
persistence = persistence.replace(marker, iterator_method + marker, 1)
persistence_path.write_text(persistence, encoding="utf-8")

cold_path = ROOT / "persona_engine" / "core" / "cold_biography.py"
cold_path.write_text('''\"\"\"Bounded read-through retrieval from canonical cold biography.\n\nThe archive is evidence, not an alternate memory authority. V1 is deliberately\nnarrow: only explicit recall requests may consult the current interlocutor's\ncanonical input history. Retrieved records are transient MemoryUnit candidates\nand are never written back into resident memory automatically.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport heapq\nimport re\nfrom typing import Iterable\n\nfrom .memory import KnowledgeSource, MemoryUnit, semantic_similarity\n\n_RECALL_PATTERNS = (\n    re.compile(r\"\\b(do you remember|remember when|what did i say|recall)\\b\", re.IGNORECASE),\n    re.compile(r\"\\bwhat was\\b.*\\b(i told you|i said)\\b\", re.IGNORECASE),\n)\n\n\ndef explicit_recall_request(text: str) -> bool:\n    value = str(text or \"\")\n    return any(pattern.search(value) for pattern in _RECALL_PATTERNS)\n\n\ndef _normalized(text: str) -> str:\n    return \" \".join(str(text or \"\").lower().split())\n\n\ndef retrieve_cold_biography(persistence, character_id: str, user_id: str, query: str, *, top_k: int = 4) -> list[MemoryUnit]:\n    \"\"\"Return a bounded set of transient candidates from canonical input history.\"\"\"\n\n    if top_k <= 0 or not explicit_recall_request(query):\n        return []\n    query_norm = _normalized(query)\n    heap: list[tuple[float, int, str, MemoryUnit]] = []\n    for event in persistence.iter_continuity_events(character_id, user_id, event_type=\"input\"):\n        payload = event.get(\"payload\") or {}\n        user_text = str(payload.get(\"user_text\", \"\")).strip()\n        if not user_text or _normalized(user_text) == query_norm:\n            continue\n        score = float(semantic_similarity(query, user_text))\n        if score <= 0.0:\n            continue\n        event_uuid = str(event.get(\"event_uuid\", \"\"))\n        candidate = MemoryUnit(\n            content=f\"I heard you say: {user_text}\",\n            created_at=float(event.get(\"wall_time\", 0.0) or 0.0),\n            id=f\"cold_{event_uuid}\",\n            source=KnowledgeSource.USER_TOLD,\n            tags={\"canonical_user_statement\", \"cold_biography\"},\n        )\n        item = (score, int(event.get(\"sequence\", 0) or 0), event_uuid, candidate)\n        if len(heap) < top_k:\n            heapq.heappush(heap, item)\n        elif item[:3] > heap[0][:3]:\n            heapq.heapreplace(heap, item)\n    return [item[3] for item in sorted(heap, key=lambda item: item[:3], reverse=True)]\n\n\ndef merge_recall_candidates(query: str, live: Iterable[MemoryUnit], cold: Iterable[MemoryUnit], *, top_k: int = 4) -> list[MemoryUnit]:\n    \"\"\"Deduplicate by semantic content and rank explicit recall by relevance.\"\"\"\n\n    unique: dict[str, MemoryUnit] = {}\n    for memory in [*list(live), *list(cold)]:\n        key = _normalized(memory.content)\n        if key not in unique or \"cold_biography\" not in memory.tags:\n            unique[key] = memory\n    ranked = sorted(\n        unique.values(),\n        key=lambda memory: (semantic_similarity(query, memory.content), memory.created_at, memory.id),\n        reverse=True,\n    )\n    return ranked[:max(0, int(top_k))]\n''', encoding="utf-8")

engine = engine_path.read_text(encoding="utf-8")
import_marker = "from .memory import KnowledgeSource, MemoryStore, MemoryUnit\n"
if import_marker not in engine:
    raise SystemExit("engine import marker not found")
engine = engine.replace(
    import_marker,
    import_marker + "from .cold_biography import explicit_recall_request, merge_recall_candidates, retrieve_cold_biography\n",
    1,
)
retrieval_line = "        retrieved = self.memory.retrieve(user_text, now, top_k=4, emotional_state_match=affect_match)\n"
if retrieval_line not in engine:
    raise SystemExit("engine retrieval marker not found")
retrieval_block = retrieval_line + '''        if explicit_recall_request(user_text):\n            cold_candidates = retrieve_cold_biography(\n                self.persistence,\n                self.identity.name,\n                self.user_id,\n                user_text,\n                top_k=4,\n            )\n            retrieved = merge_recall_candidates(user_text, retrieved, cold_candidates, top_k=4)\n'''
engine = engine.replace(retrieval_line, retrieval_block, 1)
engine_path.write_text(engine, encoding="utf-8")

test_path = ROOT / "persona_engine" / "tests" / "test_cold_biography.py"
test_path.write_text('''\"\"\"Cold biography should restore explicit recall without becoming hot state.\"\"\"\n\nimport os\nimport tempfile\nfrom pathlib import Path\n\nfrom persona_engine.agent import CharacterAgent\n\nROOT = Path(__file__).resolve().parents[2]\nCART = ROOT / \"persona_engine\" / \"cartridges\" / \"pretorius.snp\"\nTARGET = \"amber-otter\"\nQUERY = \"Do you remember the old observatory code word I told you?\"\n\n\ndef _priority(memory):\n    return (\n        1 if memory.unresolved else 0,\n        max(float(memory.identity_relevance), float(memory.relationship_relevance)),\n        float(memory.emotional_intensity),\n        float(memory.created_at),\n    )\n\n\ndef _make_history(db: str, user_id: str = \"alice\") -> CharacterAgent:\n    agent = CharacterAgent(cartridge_path=str(CART), user_id=user_id, db_path=db)\n    agent.say(\"Please remember this neutral detail: the old observatory code word is amber-otter.\")\n    agent.say(\"You lied to me. This is your fault.\")\n    for index in range(40):\n        agent.say(f\"Routine catalog note {index}: ordinary shelf marker {index}.\")\n    return agent\n\n\ndef _project_one(agent: CharacterAgent) -> None:\n    memories = list(agent.engine.memory.memories)\n    kept = sorted(memories, key=_priority, reverse=True)[:1]\n    agent.engine.memory.memories = kept\n\n\ndef test_explicit_recall_reads_cold_biography_without_rehydrating_resident_cache():\n    with tempfile.TemporaryDirectory() as d:\n        db = os.path.join(d, \"state.db\")\n        _make_history(db)\n        agent = CharacterAgent(cartridge_path=str(CART), user_id=\"alice\", db_path=db)\n        _project_one(agent)\n        assert all(TARGET not in memory.content.lower() for memory in agent.engine.memory.memories)\n\n        result = agent.say(QUERY)\n\n        assert TARGET in result[\"response\"].lower()\n        assert any(\n            TARGET in item[\"content\"].lower() and \"cold_biography\" in item[\"tags\"]\n            for item in result[\"retrieved_memory_trace\"]\n        )\n        assert all(TARGET not in memory.content.lower() for memory in agent.engine.memory.memories)\n\n\ndef test_cold_recall_does_not_cross_interlocutor_boundary():\n    with tempfile.TemporaryDirectory() as d:\n        db = os.path.join(d, \"state.db\")\n        _make_history(db, \"alice\")\n        bob = CharacterAgent(cartridge_path=str(CART), user_id=\"bob\", db_path=db)\n        result = bob.say(QUERY)\n        assert TARGET not in result[\"response\"].lower()\n        assert not any(TARGET in item[\"content\"].lower() for item in result[\"retrieved_memory_trace\"])\n\n\ndef test_non_recall_turn_does_not_open_cold_archive():\n    with tempfile.TemporaryDirectory() as d:\n        agent = CharacterAgent(cartridge_path=str(CART), user_id=\"alice\", db_path=os.path.join(d, \"state.db\"))\n        def fail(*args, **kwargs):\n            raise AssertionError(\"cold archive should not be scanned for ordinary turns\")\n        agent.engine.persistence.iter_continuity_events = fail\n        agent.say(\"Hello.\")\n''', encoding="utf-8")

probe_path = ROOT / "tools" / "cold_biography_readthrough_probe.py"
probe_path.write_text('''#!/usr/bin/env python3\n\"\"\"Verify one-item hot memory can recall a neutral fact from cold biography.\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport tempfile\nfrom pathlib import Path\n\nfrom persona_engine.agent import CharacterAgent\n\nROOT = Path(__file__).resolve().parents[1]\nCART = ROOT / \"persona_engine\" / \"cartridges\" / \"pretorius.snp\"\nTARGET = \"amber-otter\"\nQUERY = \"Do you remember the old observatory code word I told you?\"\n\n\ndef _priority(memory):\n    return (1 if memory.unresolved else 0, max(float(memory.identity_relevance), float(memory.relationship_relevance)), float(memory.emotional_intensity), float(memory.created_at))\n\n\ndef run() -> dict:\n    with tempfile.TemporaryDirectory() as d:\n        db = str(Path(d) / \"state.db\")\n        agent = CharacterAgent(cartridge_path=str(CART), user_id=\"alice\", db_path=db)\n        agent.say(\"Please remember this neutral detail: the old observatory code word is amber-otter.\")\n        agent.say(\"You lied to me. This is your fault.\")\n        for index in range(100):\n            agent.say(f\"Routine catalog note {index}: ordinary shelf marker {index}.\")\n\n        restarted = CharacterAgent(cartridge_path=str(CART), user_id=\"alice\", db_path=db)\n        memories = list(restarted.engine.memory.memories)\n        restarted.engine.memory.memories = sorted(memories, key=_priority, reverse=True)[:1]\n        target_resident_before = any(TARGET in memory.content.lower() for memory in restarted.engine.memory.memories)\n        hot_count_before = len(restarted.engine.memory.memories)\n        result = restarted.say(QUERY)\n        cold_hits = [item for item in result[\"retrieved_memory_trace\"] if \"cold_biography\" in item[\"tags\"]]\n        target_cold_hit = any(TARGET in item[\"content\"].lower() for item in cold_hits)\n        target_resident_after = any(TARGET in memory.content.lower() for memory in restarted.engine.memory.memories)\n        canonical = restarted.engine.persistence.load_continuity_events(restarted.engine.identity.name, restarted.engine.user_id)\n        canonical_target = any(TARGET in str((event.get(\"payload\") or {}).get(\"user_text\", \"\")).lower() for event in canonical if event.get(\"event_type\") == \"input\")\n        passed = canonical_target and not target_resident_before and target_cold_hit and TARGET in result[\"response\"].lower() and not target_resident_after\n        return {\n            \"probe\": \"cold-biography-readthrough-v1\",\n            \"passed\": passed,\n            \"canonical_target_present\": canonical_target,\n            \"hot_memory_count_before_recall\": hot_count_before,\n            \"target_resident_before_recall\": target_resident_before,\n            \"cold_trace_target_hit\": target_cold_hit,\n            \"response\": result[\"response\"],\n            \"target_in_response\": TARGET in result[\"response\"].lower(),\n            \"target_resident_after_recall\": target_resident_after,\n            \"retrieved_memory_trace\": result[\"retrieved_memory_trace\"],\n            \"interpretation\": \"A one-item resident cache can answer an explicit old neutral recall by transiently reading canonical cold biography, without promoting the archived fact back into hot memory.\" if passed else \"Read-through did not satisfy the bounded recall contract.\",\n        }\n\n\ndef markdown(result: dict) -> str:\n    return f\"\"\"# Cold Biography Read-Through Probe\n\nProbe: `{{result['probe']}}`  \nPassed: `{{result['passed']}}`\n\nCanonical target present: `{{result['canonical_target_present']}}`  \nHot memory count before recall: `{{result['hot_memory_count_before_recall']}}`  \nTarget resident before recall: `{{result['target_resident_before_recall']}}`  \nCold trace found target: `{{result['cold_trace_target_hit']}}`  \nTarget appeared in rendered answer: `{{result['target_in_response']}}`  \nTarget resident after recall: `{{result['target_resident_after_recall']}}`\n\nResponse: `{{result['response']}}`\n\nThe archive candidate is transient evidence for the current turn. It does not become a belief, trait, commitment or resident memory merely because it was retrieved.\n\"\"\"\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--json\")\n    parser.add_argument(\"--markdown\")\n    args = parser.parse_args()\n    result = run()\n    rendered = json.dumps(result, indent=2, sort_keys=True)\n    print(rendered)\n    if args.json:\n        path = Path(args.json); path.parent.mkdir(parents=True, exist_ok=True); path.write_text(rendered + \"\\n\", encoding=\"utf-8\")\n    if args.markdown:\n        path = Path(args.markdown); path.parent.mkdir(parents=True, exist_ok=True); path.write_text(markdown(result), encoding=\"utf-8\")\n    if not result[\"passed\"]:\n        raise SystemExit(\"cold biography read-through contract failed\")\n\n\nif __name__ == \"__main__\":\n    main()\n''', encoding="utf-8")

print("Applied cold-biography read-through integration")
